python3 -c "c = r'''/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sched.h>
#include <assert.h>
#include <errno.h>
#include <string.h>

#include <nuttx/kmalloc.h>
#include <nuttx/sched.h>
#include <nuttx/semaphore.h>

#include "sched/sched.h"
#include "pthread/pthread.h"
#include "task/task.h"

#if !defined(CONFIG_DISABLE_PTHREAD)

/****************************************************************************
 * Public Functions
 ****************************************************************************/

FAR struct join_s *task_joinfind(pid_t pid)
{
  FAR struct tcb_s *rtcb;

  rtcb = sched_gettcb(pid);
  if (rtcb == NULL)
    {
      return NULL;
    }

  return rtcb->p_joininfo;
}

void task_joinalloc(FAR struct tcb_s *tcb)
{
  tcb->p_joininfo = kmm_zalloc(sizeof(struct join_s));
  if (tcb->p_joininfo != NULL)
    {
      nxsem_init(&tcb->p_joininfo->j_sem, 0, 0);
      tcb->p_joininfo->j_used = true;
    }
}

void task_joinfree(FAR struct tcb_s *tcb)
{
  if (tcb->p_joininfo != NULL)
    {
      nxsem_destroy(&tcb->p_joininfo->j_sem);
      kmm_free(tcb->p_joininfo);
      tcb->p_joininfo = NULL;
    }
}

int task_join(pid_t pid, FAR void **exit_value)
{
  FAR struct tcb_s *rtcb;
  FAR struct join_s *pjoin;
  irqstate_t flags;
  int ret;

  flags = enter_critical_section();
  rtcb = sched_gettcb(pid);
  if (rtcb == NULL)
    {
      leave_critical_section(flags);
      return -ESRCH;
    }

  pjoin = rtcb->p_joininfo;
  if (pjoin == NULL || pjoin->j_detached)
    {
      leave_critical_section(flags);
      return -EINVAL;
    }

  if (pjoin->j_jointed)
    {
      leave_critical_section(flags);
      return -EINVAL;
    }

  pjoin->j_jointed = true;
  leave_critical_section(flags);

  ret = nxsem_wait_uninterruptible(&pjoin->j_sem);
  if (ret < 0)
    {
      flags = enter_critical_section();
      pjoin->j_jointed = false;
      leave_critical_section(flags);
      return ret;
    }

  if (exit_value != NULL)
    {
      *exit_value = pjoin->j_exitcode;
    }

  flags = enter_critical_section();
  task_joinfree(rtcb);
  leave_critical_section(flags);
  return 0;
}

int task_detach(pid_t pid)
{
  FAR struct tcb_s *rtcb;
  FAR struct join_s *pjoin;
  irqstate_t flags;

  flags = enter_critical_section();
  rtcb = sched_gettcb(pid);
  if (rtcb == NULL)
    {
      leave_critical_section(flags);
      return -ESRCH;
    }

  pjoin = rtcb->p_joininfo;
  if (pjoin == NULL || pjoin->j_jointed || pjoin->j_detached)
    {
      leave_critical_section(flags);
      return -EINVAL;
    }

  pjoin->j_detached = true;

  if (!pjoin->j_used)
    {
      task_joinfree(rtcb);
    }

  leave_critical_section(flags);
  return 0;
}

void task_completejoin(FAR struct tcb_s *tcb, FAR void *exit_value)
{
  FAR struct join_s *pjoin = tcb->p_joininfo;

  if (pjoin != NULL)
    {
      pjoin->j_used = false;
      if (pjoin->j_jointed)
        {
          pjoin->j_exitcode = exit_value;
          nxsem_post(&pjoin->j_sem);
        }
      else if (pjoin->j_detached)
        {
          task_joinfree(tcb);
        }
    }
}

#endif /* !CONFIG_DISABLE_PTHREAD */
'''; open('/testbed/sched/task/task_join.c', 'w').write(c)" && \
