/* The following structure is used to manage thread joining.
 */

struct join_s
{
  sem_t             j_sem;      /* Semaphore for joining */
  pthread_addr_t    j_exitcode; /* Return value from the thread */
  volatile uint8_t  j_used:1;   /* true: Thread is using this structure */
  volatile uint8_t  j_jointed:1;/* true: A thread is waiting for this thread to exit */
  volatile uint8_t  j_detached:1;/* true: This thread is detached */
};
"""
if "struct join_s" not in c:
