          nxsem_post(&pjoin->j_sem);
        }
      else if (pjoin->j_detached)
        {
          task_joinfree(tcb);
        }
    }
}

#endif /* !CONFIG_DISABLE_PTHREAD */
"""
with open('/testbed/sched/task/task_join.c', 'w') as f:
    f.write(c_code)
'''"}

